using System.Windows.Input;
using System.Collections.ObjectModel;
using DrawVerify.Core.Authorization;
using DrawVerify.Core.Configuration;
using DrawVerify.Core.Enums;
using DrawVerify.Core.Interfaces;
using DrawVerify.Core.Models;
namespace DrawVerify.App.ViewModels;
public sealed class WorkflowConfigurationViewModel : TaskScreenViewModel
{
    private readonly IWorkflowConfigurationService _service; private readonly ISessionAuthenticationService _session; private readonly RoleAuthorization _authorization; private readonly ICentralizedLogger? _logger;
    private string _message=string.Empty; private string _errors=string.Empty; private WorkflowConfiguration? _configuration;
    public ObservableCollection<WorkflowRoleDefinition> Roles { get; } = new();
    public ObservableCollection<WorkflowStageDefinition> Stages { get; } = new();
    public ObservableCollection<WorkflowTriggerDefinition> Triggers { get; } = new();
    public ObservableCollection<WorkflowStatusTransition> StatusTransitions { get; } = new();
    public ObservableCollection<WorkflowNotificationRule> Notifications { get; } = new();
    public ObservableCollection<KeyValuePair<WorkflowStatus, string>> StatusLabels { get; } = new();
    public WorkflowRevisionPolicy RevisionPolicy { get; private set; } = new();
    public WorkflowRolloutPolicy RolloutPolicy { get; set; } = WorkflowRolloutPolicy.CaptureAtWorkflowStart;
    public ICommand AddRoleCommand { get; } public ICommand RemoveRoleCommand { get; } public ICommand AddStageCommand { get; } public ICommand RemoveStageCommand { get; }
    public ICommand AddTriggerCommand { get; } public ICommand RemoveTriggerCommand { get; } public ICommand AddTransitionCommand { get; } public ICommand RemoveTransitionCommand { get; }
    public ICommand AddNotificationCommand { get; } public ICommand RemoveNotificationCommand { get; }
    public WorkflowConfigurationViewModel(IWorkflowConfigurationService service, ISessionAuthenticationService session, RoleAuthorization authorization, ICentralizedLogger? logger=null) { _service=service; _session=session; _authorization=authorization; _logger=logger; SaveCommand=new Command(async _=>await SaveAsync(), _=>CanEdit); PreviewCommand=new Command(async _=>await PreviewAsync(), _=>CanEdit); AddRoleCommand=new Command(_=>Roles.Add(new WorkflowRoleDefinition { DisplayName="New Role", SystemRole=SystemRoles.Viewer }), _=>CanEdit); RemoveRoleCommand=new Command(item=>{if(item is WorkflowRoleDefinition role) Roles.Remove(role);}, _=>CanEdit); AddStageCommand=new Command(_=>Stages.Add(new WorkflowStageDefinition { Name="New Stage" }), _=>CanEdit); RemoveStageCommand=new Command(item=>{if(item is WorkflowStageDefinition stage) Stages.Remove(stage);}, _=>CanEdit); AddTriggerCommand=new Command(_=>Triggers.Add(new WorkflowTriggerDefinition { Name="New Trigger" }), _=>CanEdit); RemoveTriggerCommand=new Command(item=>{if(item is WorkflowTriggerDefinition trigger) Triggers.Remove(trigger);}, _=>CanEdit); AddTransitionCommand=new Command(_=>StatusTransitions.Add(new WorkflowStatusTransition()), _=>CanEdit); RemoveTransitionCommand=new Command(item=>{if(item is WorkflowStatusTransition transition) StatusTransitions.Remove(transition);}, _=>CanEdit); AddNotificationCommand=new Command(_=>Notifications.Add(new WorkflowNotificationRule { Event=WorkflowNotificationEvent.Submission, ContentTemplate="" }), _=>CanEdit); RemoveNotificationCommand=new Command(item=>{if(item is WorkflowNotificationRule notification) Notifications.Remove(notification);}, _=>CanEdit); _=LoadAsync(); }
    public bool CanEdit => _session.IsAuthenticated && _authorization.IsAllowed(_session.CurrentUser, RolePermission.ManageGlobalConfiguration);
    public WorkflowConfiguration? Configuration { get=>_configuration; private set { _configuration=value; RaisePropertyChanged(nameof(Configuration)); RaisePropertyChanged(nameof(RolesSummary)); } }
    public string RolesSummary => string.Join(", ", Configuration?.Roles.Select(x=>$"{x.DisplayName} ({x.SystemRole})") ?? Array.Empty<string>());
    public string Message { get=>_message; private set { _message=value; RaisePropertyChanged(nameof(Message)); } }
    public string ValidationErrors { get=>_errors; private set { _errors=value; RaisePropertyChanged(nameof(ValidationErrors)); } }
    public ICommand SaveCommand { get; } public ICommand PreviewCommand { get; }
    private async Task LoadAsync() { try { Configuration=await _service.GetAsync(); Roles.Clear(); foreach(var item in Configuration.Roles) Roles.Add(item); Stages.Clear(); foreach(var item in Configuration.Stages) Stages.Add(item); Triggers.Clear(); foreach(var item in Configuration.Triggers) Triggers.Add(item); StatusTransitions.Clear(); foreach(var item in Configuration.StatusTransitions) StatusTransitions.Add(item); Notifications.Clear(); foreach(var item in Configuration.Notifications) Notifications.Add(item); StatusLabels.Clear(); foreach(var item in Configuration.StatusLabels) StatusLabels.Add(item); RevisionPolicy=Configuration.RevisionPolicy; RolloutPolicy=Configuration.RolloutPolicy; RaisePropertyChanged(nameof(RevisionPolicy)); RaisePropertyChanged(nameof(RolloutPolicy)); } catch(UnauthorizedAccessException ex) { Message="Workflow configuration access denied."; ValidationErrors=ex.Message; } catch(Exception ex) { _logger?.Log(ex,"Workflow configuration UI load","Unable to load workflow configuration."); Message="Unable to load workflow configuration."; ValidationErrors=ex.Message; } }
    private async Task SaveAsync() { try { if(Configuration is null)return; var labels=StatusLabels.ToDictionary(x=>x.Key,x=>x.Value); var edited=Configuration with { Roles=Roles.ToArray(), Stages=Stages.ToArray(), Triggers=Triggers.ToArray(), StatusTransitions=StatusTransitions.ToArray(), Notifications=Notifications.ToArray(), StatusLabels=labels, RevisionPolicy=RevisionPolicy, RolloutPolicy=RolloutPolicy }; Configuration=await _service.SaveAsync(edited,edited.Version); Message="Workflow configuration saved."; IsDirty=false; ValidationErrors=string.Empty; } catch(UnauthorizedAccessException ex) { Message="Workflow configuration access denied."; ValidationErrors=ex.Message; } catch(InvalidOperationException ex) { Message="Workflow configuration is invalid."; ValidationErrors=ex.Message; } catch(Exception ex) { _logger?.Log(ex,"Workflow configuration UI save","Unable to save workflow configuration."); Message="Unable to save workflow configuration."; ValidationErrors=ex.Message; } }
    private async Task PreviewAsync() { try { if(Configuration is null)return; var result=await _service.PreviewAsync(Configuration,new WorkflowPreviewMetadata()); Message=result.MatchesTrigger?"Preview: workflow matches configured triggers.":"Preview: no workflow trigger matches."; } catch(InvalidOperationException ex) { ValidationErrors=ex.Message; } catch(Exception ex) { _logger?.Log(ex,"Workflow configuration UI preview","Unable to preview workflow configuration."); Message="Unable to preview workflow configuration."; } }
    private sealed class Command(Action<object?> execute, Predicate<object?> canExecute):ICommand { public event EventHandler? CanExecuteChanged; public bool CanExecute(object? p)=>canExecute(p); public void Execute(object? p)=>execute(p); }
}
